  "films.cues.1": ["قبل الموسيقى، كانت الحيوانات تغير على الحقول أكثر، والخنازير البرية خاصة.", "أما الآن، مع الموسيقى، فهي تبتعد.", "والنباتات تبدو أكثر حيوية أيضًا.", "لم تعد تبدو متعطّشة للسماد والماء. صارت أنضر وأجمل."],
  "films.cues.2": ["حين شغّلنا الموسيقى، ابتعدت الآفات عن البطيخ والشمّام.", "خفّضنا سياج الخنازير البرية من ثلاثة أسلاك إلى سلك واحد، ومع ذلك بقيت بعيدة طوال العام.", "والموسيقى جميلة جدًا."],
  "films.cues.3": ["مرحبًا بالجميع. بدأنا نُسمِع نباتاتنا الموسيقى.", "أول ما لاحظته تستطيعون رؤيته هنا.", "حصدنا خضرواتنا الورقية قبل موعدها بخمسة عشر يومًا،", "وخيرها ينتقل من النباتات إلينا أيضًا.", "جرّبوها. لن تخسروا شيئًا."],
  "films.cues.5": ["بفضل الموسيقى التي أهدانا إياها معلّمنا، محصولنا رائع.", "الدجاجات سعيدة جدًا.", "شكرًا جزيلًا."]
